import { mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import type { ScanCache } from "./types.js";

const ACTIVE_SCAN_LOCKS = new Set<string>();
const DEFAULT_CACHE_MAX_AGE_MS = 24 * 60 * 60 * 1000;

/**
 * Resolve the persisted cache file path for a workspace hash.
 */
export function resolveCachePath(workspaceHash: string): string {
	const cacheDir = join(homedir(), ".vreko", "cache", "init-scan");
	mkdirSync(cacheDir, { recursive: true });
	return join(cacheDir, `${workspaceHash}.json`);
}

/**
 * Returns true when a cached scan is still fresh.
 */
export function isCacheValid(cache: ScanCache | null, maxAgeMs = DEFAULT_CACHE_MAX_AGE_MS): cache is ScanCache {
	if (!cache) {
		return false;
	}

	const cachedAt = Date.parse(cache.lastScannedAt);
	if (!Number.isFinite(cachedAt)) {
		return false;
	}

	return Date.now() - cachedAt < maxAgeMs;
}

/**
 * Check whether a scan lock is currently held for the workspace.
 */
export function isScanInProgress(workspaceHash: string): boolean {
	return ACTIVE_SCAN_LOCKS.has(workspaceHash);
}

/**
 * Acquire a process-local scan lock. Returns null if already locked.
 */
export function acquireScanLock(workspaceHash: string): (() => void) | null {
	if (ACTIVE_SCAN_LOCKS.has(workspaceHash)) {
		return null;
	}

	ACTIVE_SCAN_LOCKS.add(workspaceHash);
	let released = false;

	return () => {
		if (released) {
			return;
		}
		released = true;
		ACTIVE_SCAN_LOCKS.delete(workspaceHash);
	};
}
