import { EventEmitter } from "node:events";
import type { EarlyDiscovery, DiscoveryEmitter as IDiscoveryEmitter } from "./types";

export class DiscoveryEmitter extends EventEmitter implements IDiscoveryEmitter {
	emitDiscovery(discovery: EarlyDiscovery): void {
		if (discovery.confidence > 0.85) {
			this.emit("discovery", discovery);
		}
	}
}

export function createDiscoveryEmitter(): DiscoveryEmitter {
	return new DiscoveryEmitter();
}
