import { execFile } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { promisify } from "node:util";
import type { ScanCache } from "./types";

const execFileAsync = promisify(execFile);

export function writeScanCache(path: string, cache: ScanCache): void {
	writeFileSync(path, JSON.stringify(cache, null, 2));
}

export function readScanCache(path: string): ScanCache | null {
	if (!existsSync(path)) {
		return null;
	}
	try {
		const data = JSON.parse(readFileSync(path, "utf-8"));
		// Validate essential fields
		if (!data.lastScannedHead || !data.lastScannedAt) {
			return null;
		}
		return data as ScanCache;
	} catch {
		return null;
	}
}

/**
 * Compute the delta between the cached scan and the current HEAD.
 * If the cache's lastScannedHead is still an ancestor of current HEAD,
 * we only need to re-scan the commits between them.
 * If it's not an ancestor (force push, reset), we re-scan everything.
 */
export async function computeDelta(
	cache: ScanCache,
	repoPath: string,
): Promise<{ needsFullScan: boolean; commitRange?: { from: string; to: string; count: number } }> {
	try {
		// Get current HEAD
		const { stdout: currentHead } = await execFileAsync("git", ["rev-parse", "HEAD"], {
			cwd: repoPath,
			timeout: 5000,
		});
		const head = currentHead.trim();

		// If HEAD hasn't changed, no scan needed
		if (head === cache.lastScannedHead) {
			return { needsFullScan: false };
		}

		// Check if cached HEAD is an ancestor of current HEAD
		try {
			await execFileAsync("git", ["merge-base", "--is-ancestor", cache.lastScannedHead, head], {
				cwd: repoPath,
				timeout: 5000,
			});

			// It IS an ancestor  -  compute delta commit count
			const { stdout: countOut } = await execFileAsync(
				"git",
				["rev-list", "--count", `${cache.lastScannedHead}..${head}`],
				{ cwd: repoPath, timeout: 5000 },
			);
			const count = Number.parseInt(countOut.trim(), 10) || 0;

			return {
				needsFullScan: false,
				commitRange: {
					from: cache.lastScannedHead,
					to: head,
					count,
				},
			};
		} catch {
			// Not an ancestor  -  force push or history rewrite, need full scan
			return { needsFullScan: true };
		}
	} catch {
		// Can't determine delta, do full scan
		return { needsFullScan: true };
	}
}
