import { existsSync } from "node:fs";
import { join } from "node:path";
import { isArtifactFile } from "./gitlog-analyzer.js";
import { generateInsights } from "./insight-generator.js";
import type {
	AllSignals,
	BaselineResponse,
	CoChangeEdge,
	CoChangePersisted,
	FileChurnEntry,
	FragilityEntry,
	RecommendedConfig,
	RecoveryRiskProfile,
	RiskDriver,
	TopologyInitSignals,
	WatchTarget,
} from "./types";

function clamp(value: number, min = 0, max = 100): number {
	return Math.max(min, Math.min(max, value));
}

/**
 * Compute Recovery Risk dimension (0-100).
 * Sources: resetToHEADCount, rollbackCorrelation, revert rates.
 */
function computeRecoveryRisk(signals: AllSignals): number {
	const reflog = signals.reflog;
	const gitlog = signals.gitlog;

	let score = 0;

	// Reset-to-HEAD count: each reset contributes, diminishing returns
	if (reflog) {
		score += Math.min(reflog.resetToHEADCount * 3, 40);
		score += Math.min(reflog.forceResetRate * 5, 15);
	}

	// Rollback correlation: higher correlation = higher risk
	if (gitlog) {
		const rc = gitlog.rollbackCorrelation;
		score += Math.min(rc.resetAfterLargeCommitRate * 0.3, 15);
		score += Math.min(rc.resetAfterCrossPackageRate * 0.3, 10);

		// Revert count from file churn
		const totalReverts = gitlog.fileChurnRanking.reduce((s, f) => s + f.revertCount, 0);
		score += Math.min(totalReverts * 2, 20);
	}

	return clamp(score);
}

/**
 * Compute Change Volatility dimension (0-100).
 * Sources: reflog churn, force pushes, commit diffusion.
 */
function computeChangeVolatility(signals: AllSignals): number {
	const reflog = signals.reflog;
	const gitlog = signals.gitlog;

	let score = 0;

	if (reflog) {
		// Force reset rate: each per week adds risk
		score += Math.min(reflog.forceResetRate * 4, 20);
		// Rebase frequency: moderate signal
		score += Math.min(reflog.rebaseFrequency * 2, 10);
		// Branch abandonment
		score += Math.min(reflog.branchAbandonmentRate * 0.2, 10);
	}

	if (gitlog) {
		const d = gitlog.diffusion;
		// Cross-directory diffusion is a strong volatility signal
		score += Math.min(d.crossDirectoryDiffusionRate * 0.5, 20);
		// Large commit ratio
		score += Math.min(gitlog.largeCommitRatio * 0.4, 15);
		// Large session clusters
		score += Math.min(d.largeSessionClusterRate * 0.5, 15);
		// High commit frequency variance
		score += Math.min(gitlog.commitFrequencyVariance * 2, 10);
	}

	return clamp(score);
}

/**
 * Compute Workflow Fragility dimension (0-100).
 * Sources: fragile files, co-change instability, test adjacency gaps.
 */
function computeWorkflowFragility(signals: AllSignals): number {
	const gitlog = signals.gitlog;
	const structure = signals.structure;

	let score = 0;

	if (gitlog) {
		// Fragile hotspot files (high churn + reverts)
		const fragileCount = gitlog.fileChurnRanking.filter((f) => f.revertCount > 0 && f.changeCount > 5).length;
		score += Math.min(fragileCount * 5, 25);

		// Co-change instability: high-confidence pairs indicate tight coupling
		const unstablePairs = gitlog.coChangeGraph.filter((e) => e.confidence > 0.7);
		score += Math.min(unstablePairs.length * 3, 15);

		// Hotspot file concentration
		score += Math.min(gitlog.hotspotFiles.length * 2, 10);
	}

	if (structure) {
		// Test adjacency gaps
		const testGap = 100 - structure.testAdjacency.overallTestAdjacencyScore;
		score += Math.min(testGap * 0.3, 20);

		// Weakly tested hotspots
		score += Math.min(structure.testAdjacency.weaklyTestedHotspots.length * 5, 15);

		// Sensitive surfaces
		score += Math.min(structure.sensitiveSurfaces.sensitivePathCount * 3, 15);
	}

	return clamp(score);
}

/**
 * Compute complexity dimension (secondary, 0-100).
 */
function computeComplexity(signals: AllSignals): number {
	const structure = signals.structure;
	if (!structure) {
		return 0;
	}

	let score = 0;
	score += Math.min(structure.configFileCount * 2, 30);

	// Monorepo depth
	const packageCount = structure.testAdjacency.packageTestAdjacency.length;
	score += Math.min(packageCount * 3, 30);

	score += Math.min(structure.gitignoreComplexity, 20);
	score += structure.repoType.startsWith("monorepo") ? 20 : 0;

	return clamp(score);
}

/**
 * Compute collaboration dimension (secondary, 0-100).
 */
function computeCollaboration(signals: AllSignals): number {
	const gitlog = signals.gitlog;
	if (!gitlog) {
		return 0;
	}

	let score = 0;
	// Higher contributor count = more collaboration
	score += Math.min(gitlog.contributorCount * 5, 30);
	// Merge frequency
	score += Math.min(gitlog.mergeConflictFrequency * 0.5, 20);
	// Low bus factor = higher risk
	if (gitlog.busFactorEstimate <= 1) {
		score += 30;
	} else if (gitlog.busFactorEstimate <= 2) {
		score += 15;
	}

	return clamp(score);
}

/**
 * Compute structural risk dimension (secondary, 0-100).
 * Sources: circular chains, high fan-in files, rule violations, orphans, edge density.
 */
export function calculateStructuralRisk(topology: TopologyInitSignals | null): number {
	if (!topology) {
		return 0;
	}

	let score = 0;

	// Circular chains: each chain is a strong risk signal
	score += Math.min(30, topology.circularChainCount * 8);

	// High fan-in ratio: proportion of files with high import count
	const highFanInRatio = topology.highFanInFiles.length / Math.max(topology.moduleCount, 1);
	score += Math.min(25, highFanInRatio * 500);

	// Rule violations: each violation adds modest risk
	score += Math.min(20, topology.ruleViolationCount * 3);

	// Orphan ratio: disconnected files indicate structural issues
	const orphanRatio = topology.orphanFileCount / Math.max(topology.moduleCount, 1);
	score += Math.min(15, orphanRatio * 150);

	// Edge density: very high density indicates tight coupling
	const edgeDensity = topology.edgeCount / Math.max(topology.moduleCount, 1);
	if (edgeDensity > 10) {
		score += 10;
	}

	return Math.min(100, Math.round(score));
}

/**
 * Compute AI exposure dimension (secondary, 0-100).
 * Checks for AI tool config files and applies tool-specific risk adjustments.
 */
function computeAiExposure(repoPath?: string, toolIdentity?: { tool: string; confidence: number }): number {
	if (!repoPath) {
		return 0;
	}

	let score = 0;

	// EXISTING: Check for AI tool config directories
	const aiIndicators = [
		".cursor",
		".github/copilot",
		".codeium",
		".continue",
		".aider",
		".windsurf",
		".claude",
		".augment",
		".roo",
	];

	for (const indicator of aiIndicators) {
		if (existsSync(join(repoPath, indicator))) {
			score += 15;
		}
	}

	// NEW: Tool-specific risk adjustment from ToolIdentityService
	if (toolIdentity && toolIdentity.confidence >= 0.5) {
		const TOOL_RISK_MULTIPLIERS: Record<string, number> = {
			devin: 1.4,
			"claude-code": 1.2,
			cursor: 1.0,
			"github-copilot": 0.9,
			windsurf: 1.0,
			augment: 1.0,
			cline: 1.1,
			roocode: 1.1,
			aider: 1.0,
		};
		const multiplier = TOOL_RISK_MULTIPLIERS[toolIdentity.tool] ?? 1.0;
		score = Math.round(score * multiplier);
	}

	// NEW: Branch pattern detection (lightweight, no full git log)
	try {
		const { execSync } = require("node:child_process");
		const currentBranch = execSync("git rev-parse --abbrev-ref HEAD", {
			cwd: repoPath,
			timeout: 5000,
			encoding: "utf-8",
		}).trim();

		// Devin branch pattern: devin/{timestamp}-*
		if (/^devin\/\d{10}-/.test(currentBranch)) {
			score += 10;
		}
	} catch {
		// Git not available  -  skip
	}

	return clamp(score);
}

/**
 * Build the top risk drivers from signal analysis.
 */
function buildTopDrivers(signals: AllSignals): RiskDriver[] {
	const drivers: RiskDriver[] = [];

	if (signals.reflog && signals.reflog.resetToHEADCount > 3) {
		drivers.push({
			id: "repeated-recoveries",
			label: "Repeated recovery events",
			scoreImpact: Math.min(signals.reflog.resetToHEADCount * 3, 40),
			evidence: [
				`${signals.reflog.resetToHEADCount} reset-to-HEAD events detected`,
				signals.reflog.avgTimeBetweenResets > 0
					? `Average ${Math.round(signals.reflog.avgTimeBetweenResets)} minutes between resets`
					: "Multiple resets in short timeframe",
			],
			protectiveAction: "Increase snapshot density during volatile periods",
		});
	}

	if (signals.gitlog) {
		const rc = signals.gitlog.rollbackCorrelation;
		if (rc.resetAfterLargeCommitRate > 20 || rc.resetAfterCrossPackageRate > 20) {
			drivers.push({
				id: "rollback-correlation",
				label: `Recoveries correlate with ${rc.topRecoveryTrigger.replace(/-/g, " ")} changes`,
				scoreImpact: Math.max(rc.resetAfterLargeCommitRate, rc.resetAfterCrossPackageRate) * 0.3,
				evidence: [
					rc.resetAfterLargeCommitRate > 0
						? `${Math.round(rc.resetAfterLargeCommitRate)}% of reverts follow large commits`
						: "",
					rc.resetAfterCrossPackageRate > 0
						? `${Math.round(rc.resetAfterCrossPackageRate)}% of reverts follow cross-package changes`
						: "",
				].filter(Boolean),
				protectiveAction: "Auto-snapshot before high-diffusion commits",
			});
		}

		if (signals.gitlog.hotspotFiles.length > 0) {
			const topChurn = signals.gitlog.fileChurnRanking[0];
			drivers.push({
				id: "fragile-hotspots",
				label: "Fragile file hotspots detected",
				scoreImpact: Math.min(signals.gitlog.hotspotFiles.length * 5, 25),
				evidence: [
					topChurn
						? `${topChurn.path} changed ${topChurn.changeCount} times (${topChurn.revertCount} reverts)`
						: "Multiple high-churn files with reverts",
				],
				protectiveAction: "Watch fragile files with enhanced monitoring",
			});
		}

		if (signals.gitlog.diffusion.crossDirectoryDiffusionRate > 20) {
			drivers.push({
				id: "cross-directory-blast",
				label: "High cross-directory change diffusion",
				scoreImpact: Math.min(signals.gitlog.diffusion.crossDirectoryDiffusionRate * 0.5, 20),
				evidence: [
					`${Math.round(signals.gitlog.diffusion.crossDirectoryDiffusionRate)}% of commits span multiple directories`,
				],
				protectiveAction: "Track cross-directory blast radius",
			});
		}
	}

	if (signals.structure?.testAdjacency.weaklyTestedHotspots.length) {
		drivers.push({
			id: "weak-test-coverage",
			label: "Weakly-tested high-churn areas",
			scoreImpact: Math.min(signals.structure.testAdjacency.weaklyTestedHotspots.length * 5, 15),
			evidence: signals.structure.testAdjacency.weaklyTestedHotspots.map(
				(p) => `${p} has high churn but low test coverage`,
			),
			protectiveAction: "Prioritize snapshot protection for untested hotspots",
		});
	}

	// Sort by scoreImpact descending, return top 5
	return drivers.sort((a, b) => b.scoreImpact - a.scoreImpact).slice(0, 5);
}

/**
 * Build recommended configuration from signals.
 */
function buildRecommendedConfig(signals: AllSignals, recoveryRisk: number): RecommendedConfig {
	// Protection level based on overall risk
	const protectionLevel: RecommendedConfig["protectionLevel"] =
		recoveryRisk > 70 ? "maximum" : recoveryRisk > 40 ? "enhanced" : "standard";

	const snapshotFrequency: RecommendedConfig["snapshotFrequency"] =
		recoveryRisk > 70 ? "aggressive" : recoveryRisk > 40 ? "balanced" : "conservative";

	const watchTargets: WatchTarget[] = [];

	// Add hotspot files
	if (signals.gitlog) {
		for (const file of signals.gitlog.hotspotFiles.slice(0, 5)) {
			const churnEntry = signals.gitlog.fileChurnRanking.find((f) => f.path === file);
			watchTargets.push({
				path: file,
				fileCount: 1,
				reason: churnEntry?.revertCount ? "fragile detected" : "high churn",
			});
		}

		// Add co-change pair directories
		for (const edge of signals.gitlog.coChangeGraph.slice(0, 3)) {
			if (edge.confidence > 0.7) {
				const dir = edge.fileA.includes("/") ? edge.fileA.substring(0, edge.fileA.lastIndexOf("/")) : ".";
				if (!watchTargets.some((t) => t.path === dir)) {
					watchTargets.push({
						path: dir,
						fileCount: 2,
						reason: "co-change patterns",
					});
				}
			}
		}
	}

	// Add weakly-tested directories
	if (signals.structure) {
		for (const hotspot of signals.structure.testAdjacency.weaklyTestedHotspots.slice(0, 3)) {
			if (!watchTargets.some((t) => t.path === hotspot)) {
				watchTargets.push({
					path: hotspot,
					fileCount: 0,
					reason: "weak test coverage",
				});
			}
		}
	}

	// Fallback: repos with insufficient history for hotspot/co-change detection
	// (no file changed > 5× and no reverts) would always show "Watching: 0 targets".
	// Seed from the top churned files (any changeCount > 0) so new repos see real
	// targets from day one instead of an empty state.
	if (watchTargets.length === 0 && signals.gitlog?.fileChurnRanking.length) {
		const topChurned = [...signals.gitlog.fileChurnRanking]
			.filter((f) => f.changeCount > 0)
			.sort((a, b) => b.changeCount - a.changeCount)
			.slice(0, 5);
		for (const file of topChurned) {
			watchTargets.push({
				path: file.path,
				fileCount: 1,
				reason: "frequently changed",
			});
		}
	}

	const enabledFeatures: string[] = ["real-time-protection"];
	if (recoveryRisk > 50) {
		enabledFeatures.push("pre-commit-snapshot");
	}
	if (signals.gitlog?.coChangeGraph.length) {
		enabledFeatures.push("co-change-tracking");
	}

	return { protectionLevel, snapshotFrequency, watchTargets, enabledFeatures };
}

/**
 * Determine the overall risk tier from the primary recovery risk score.
 */
function riskTier(score: number): RecoveryRiskProfile["overallRisk"] {
	if (score > 75) {
		return "high";
	}
	if (score > 50) {
		return "elevated";
	}
	if (score > 25) {
		return "moderate";
	}
	return "low";
}

/**
 * Compute confidence based on how many scanners returned data.
 */
function computeConfidence(signals: AllSignals): number {
	let sources = 0;
	let weight = 0;
	if (signals.reflog) {
		sources++;
		weight += 0.4;
	}
	if (signals.gitlog) {
		sources++;
		weight += 0.4;
	}
	if (signals.structure) {
		sources++;
		weight += 0.2;
	}
	return sources === 0 ? 0.1 : weight;
}

/**
 * Return up to 20 files ranked by revert *rate* (revertCount / changeCount) for
 * bootstrap seeding. Only files that have actually been reverted at least once are
 * considered fragile by this measure  -  others represent busy but stable files.
 *
 * Minimum changeCount of 5 prevents noise: a file changed twice and reverted once
 * is not statistically meaningful.
 *
 * Fallback: when no file passes the revertCount > 0 filter (e.g. a brand-new repo
 * with no reverts yet), returns the top 5 most-changed files so the array is never
 * empty and the TUI always has seed data to display.
 *
 * NOTE: artifact files (lockfiles, package.json, generated outputs) are already
 * excluded at the fileChurnRanking source in gitlog-analyzer.ts  -  they will never
 * appear here.
 */
function buildTopFragileFiles(signals: AllSignals): Array<{ path: string; changeCount: number; revertCount: number }> {
	if (!signals.gitlog?.fileChurnRanking.length) {
		return [];
	}

	const withReverts = [...signals.gitlog.fileChurnRanking]
		.filter((f) => f.changeCount >= 3 && f.revertCount > 0)
		.sort((a, b) => b.revertCount / b.changeCount - a.revertCount / a.changeCount)
		.slice(0, 20)
		.map((f) => ({ path: f.path, changeCount: f.changeCount, revertCount: f.revertCount }));

	if (withReverts.length > 0) {
		return withReverts;
	}

	// Fallback: no reverted files  -  return top churned as seed data
	return [...signals.gitlog.fileChurnRanking]
		.filter((f) => f.changeCount > 0)
		.sort((a, b) => b.changeCount - a.changeCount)
		.slice(0, 5)
		.map((f) => ({ path: f.path, changeCount: f.changeCount, revertCount: 0 }));
}

/**
 * Find the single most fragile file ranked by revert rate (revertCount / changeCount).
 * Returns null when no file has been reverted at least once with changeCount >= 5.
 * Consistent with buildTopFragileFiles  -  callers already handle null.
 */
function findTopFragileFile(signals: AllSignals): string | null {
	if (!signals.gitlog?.fileChurnRanking.length) {
		return null;
	}

	const ranked = [...signals.gitlog.fileChurnRanking]
		.filter((f) => f.changeCount >= 3 && f.revertCount > 0)
		.sort((a, b) => b.revertCount / b.changeCount - a.revertCount / a.changeCount);

	return ranked.length > 0 ? ranked[0].path : null;
}

/**
 * Confidence weight ramps 0→1 as changeCount grows from 0 to MIN_SAMPLE.
 * A file changed fewer than MIN_SAMPLE times gets a proportionally reduced score
 * so low-sample files (2 changes, 1 revert = 50% rate) don't outrank
 * high-sample files (40 changes, 12 reverts = 30% rate).
 */
const FRAGILITY_MIN_SAMPLE = 5;
function confidenceWeight(changeCount: number): number {
	return Math.min(changeCount / FRAGILITY_MIN_SAMPLE, 1);
}

/**
 * Determine whether a file should be excluded from fragility ranking.
 * Excluded files are recorded in the fragility array but excluded=true,
 * so they are not surfaced as hotspots.
 */
function isExcludedFromFragilityRanking(filePath: string): boolean {
	// isArtifactFile already covers lockfiles, package.json, generated outputs
	return isArtifactFile(filePath);
}

/**
 * Build the full per-file fragility array from the git churn ranking.
 * Returns ALL files (including excluded) so the generated.fragility array
 * is complete. Callers filter by excluded=false to get ranked hotspots.
 */
function buildFragilityArray(signals: AllSignals): FragilityEntry[] {
	if (!signals.gitlog?.fileChurnRanking.length) {
		return [];
	}
	return signals.gitlog.fileChurnRanking.map((f: FileChurnEntry) => {
		const excluded = isExcludedFromFragilityRanking(f.path);
		const revertRate = f.changeCount > 0 ? f.revertCount / f.changeCount : 0;
		const fragilityScore = excluded ? 0 : revertRate * confidenceWeight(f.changeCount);
		return {
			file: f.path,
			changeCount: f.changeCount,
			revertCount: f.revertCount,
			revertRate,
			fragilityScore,
			excluded,
		};
	});
}

/**
 * Build co-change pairs for persistence.
 * A pair is marked generated=true when BOTH files are artifact files.
 * These are recorded but not surfaced as real coupling signals.
 */
function buildCoChangeArray(signals: AllSignals): CoChangePersisted[] {
	if (!signals.gitlog?.coChangeGraph.length) {
		return [];
	}
	return signals.gitlog.coChangeGraph.map((edge: CoChangeEdge) => ({
		files: [edge.fileA, edge.fileB] as [string, string],
		rate: edge.confidence,
		occurrences: edge.coChangeCount,
		generated: isArtifactFile(edge.fileA) && isArtifactFile(edge.fileB),
	}));
}

export function synthesize(signals: AllSignals, baseline?: BaselineResponse, repoPath?: string): RecoveryRiskProfile {
	const { insights, locked } = generateInsights(signals, baseline);

	const recoveryRisk = computeRecoveryRisk(signals);
	const changeVolatility = computeChangeVolatility(signals);
	const workflowFragility = computeWorkflowFragility(signals);

	return {
		overallRisk: riskTier(recoveryRisk),
		confidence: computeConfidence(signals),
		primary: {
			recoveryRisk,
			changeVolatility,
			workflowFragility,
		},
		secondary: {
			complexity: computeComplexity(signals),
			collaboration: computeCollaboration(signals),
			aiExposure: computeAiExposure(repoPath, undefined), // toolIdentity passed from daemon
			structuralRisk: calculateStructuralRisk(signals.topology),
		},
		topDrivers: buildTopDrivers(signals),
		insights,
		lockedInsights: [locked],
		recommendedConfig: buildRecommendedConfig(signals, recoveryRisk),
		topFragileFile: findTopFragileFile(signals),
		topFragileFiles: buildTopFragileFiles(signals),
		coChange: buildCoChangeArray(signals),
		fragility: buildFragilityArray(signals),
	};
}
