/**
 * runInitScan - Orchestrator for the full init scan pipeline
 *
 * Coordinates reflog, gitlog, structure, and (optionally) topology scanners,
 * then synthesizes a RecoveryRiskProfile. Used by the CLI TUI Scanning component.
 */

import type { TopologyProvider } from "../shared/topology-provider.js";
import { analyzeGitLog } from "./gitlog-analyzer.js";
import { scanReflog } from "./reflog-scanner.js";
import { detectStructure } from "./repo-structure.js";
import type { ScanEventEmitter } from "./scan-events.js";
import { synthesize } from "./synthesizer.js";
import type { DiscoveryEmitter, RecoveryRiskProfile, TopologyInitSignals } from "./types.js";

export interface RunInitScanOptions {
	repoPath: string;
	emitter?: DiscoveryEmitter | ScanEventEmitter;
	topologyProvider?: TopologyProvider;
}

/**
 * Run the topology scan phase via the injected provider.
 * Emits progress events and discoveries for notable findings.
 * Returns null on failure (graceful degradation).
 */
async function runTopologyScan(
	provider: TopologyProvider,
	repoPath: string,
	emitter?: DiscoveryEmitter | ScanEventEmitter,
): Promise<TopologyInitSignals | null> {
	const scanEmitter = emitter as ScanEventEmitter | undefined;

	scanEmitter?.emitProgress?.({ stage: "topology", progress: 0, message: "Analyzing dependencies..." });

	try {
		const result = await provider.scan?.(repoPath);

		if (!result) {
			scanEmitter?.emitProgress?.({
				stage: "topology",
				progress: 100,
				message: "Topology scan returned no data",
			});
			return null;
		}

		// Emit discoveries for high-fan-in files
		for (const file of result.highFanInFiles.slice(0, 3)) {
			emitter?.emitDiscovery?.({
				source: "structure",
				confidence: 0.9,
				message: `${file.path} is imported by ${file.importedByCount} files`,
				detailMessage: "Vreko will treat this as a structural hotspot with enhanced blast radius monitoring",
				relatedInsightId: "fused-structural-temporal-hotspot",
			});
		}

		// Emit discovery for circular chains
		if (result.circularChainCount > 0) {
			emitter?.emitDiscovery?.({
				source: "structure",
				confidence: 0.95,
				message: `${result.circularChainCount} circular dependency chain(s) detected`,
				detailMessage: "Circular dependencies increase change risk  -  Vreko will monitor these chains closely",
			});
		}

		scanEmitter?.emitProgress?.({
			stage: "topology",
			progress: 100,
			message: `Topology: ${result.moduleCount} modules, ${result.edgeCount} edges in ${result.cruiseDurationMs}ms`,
		});

		return result;
	} catch (_err) {
		scanEmitter?.emitProgress?.({
			stage: "topology",
			progress: 100,
			message: "Topology scan failed (non-fatal)",
		});
		return null;
	}
}

/**
 * Run the full init scan pipeline for a given repository path.
 * Runs reflog, gitlog, structure, and (optionally) topology scanners in parallel,
 * then synthesizes results.
 * Emits progress/finding/complete events if a ScanEventEmitter is provided.
 */
export async function runInitScan({
	repoPath,
	emitter,
	topologyProvider,
}: RunInitScanOptions): Promise<RecoveryRiskProfile> {
	const scanEmitter = emitter as ScanEventEmitter | undefined;

	const [reflogSignals, gitlogSignals, structureSignals, topologySignals] = await Promise.all([
		scanReflog(repoPath, emitter),
		analyzeGitLog(repoPath, emitter),
		detectStructure(repoPath, emitter),
		topologyProvider?.scan ? runTopologyScan(topologyProvider, repoPath, emitter) : Promise.resolve(null),
	]);

	scanEmitter?.emitProgress?.({ stage: "synthesis", progress: 0, message: "Synthesizing risk profile..." });

	const profile = synthesize({
		reflog: reflogSignals,
		gitlog: gitlogSignals,
		structure: structureSignals,
		topology: topologySignals,
	});

	scanEmitter?.emitProgress?.({ stage: "synthesis", progress: 100, message: "Scan complete" });
	scanEmitter?.emitComplete?.(profile);

	return profile;
}
