/**
 * Scan Event Emitter
 *
 * Extends the existing DiscoveryEmitter interface with progress, finding,
 * and complete events for real-time UI feedback during init scan.
 *
 * @module init-scan/scan-events
 */

import { EventEmitter } from "node:events";
import type { EarlyDiscovery, RecoveryRiskProfile } from "./types.js";

export interface ScanProgressEvent {
	stage: "commits" | "reflog" | "topology" | "synthesis";
	progress: number; // 0-100
	message: string;
}

export interface ScanFindingEvent {
	type: "warning" | "insight";
	text: string;
}

/**
 * Full-featured scan emitter that satisfies the DiscoveryEmitter interface
 * and adds progress/finding/complete events for UI consumption.
 */
export class ScanEventEmitter extends EventEmitter {
	// --- DiscoveryEmitter compatibility ---

	emitDiscovery(discovery: EarlyDiscovery): void {
		if (discovery.confidence > 0.85) {
			this.emit("discovery", discovery);
		}
	}

	// --- Scan-specific events ---

	emitProgress(event: ScanProgressEvent): void {
		this.emit("progress", event);
	}

	emitFinding(event: ScanFindingEvent): void {
		this.emit("finding", event);
	}

	emitComplete(profile: RecoveryRiskProfile): void {
		this.emit("complete", profile);
	}

	onDiscovery(handler: (discovery: EarlyDiscovery) => void): this {
		this.on("discovery", handler);
		return this;
	}

	onProgress(handler: (event: ScanProgressEvent) => void): this {
		this.on("progress", handler);
		return this;
	}

	onFinding(handler: (event: ScanFindingEvent) => void): this {
		this.on("finding", handler);
		return this;
	}

	onComplete(handler: (profile: RecoveryRiskProfile) => void): this {
		this.on("complete", handler);
		return this;
	}
}

export function createScanEventEmitter(): ScanEventEmitter {
	return new ScanEventEmitter();
}
