import { execFile } from "node:child_process";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { promisify } from "node:util";
import type { DiscoveryEmitter, RepoStructure, SensitiveSurfaceSignals, TestAdjacencySignals } from "./types";

const execFileAsync = promisify(execFile);

/**
 * Recursively count files matching a predicate, up to maxDepth.
 */
function countFiles(dir: string, predicate: (name: string) => boolean, maxDepth = 4, currentDepth = 0): number {
	if (currentDepth >= maxDepth || !existsSync(dir)) {
		return 0;
	}
	let count = 0;
	try {
		const entries = readdirSync(dir, { withFileTypes: true });
		for (const entry of entries) {
			if (
				entry.name === "node_modules" ||
				entry.name === ".git" ||
				entry.name === "dist" ||
				entry.name === "build"
			) {
				continue;
			}
			if (entry.isFile() && predicate(entry.name)) {
				count++;
			} else if (entry.isDirectory()) {
				count += countFiles(join(dir, entry.name), predicate, maxDepth, currentDepth + 1);
			}
		}
	} catch {
		// Permission denied or similar
	}
	return count;
}

/**
 * Check for existence of any file matching glob-like patterns.
 */
function _hasAnyFile(dir: string, patterns: string[]): boolean {
	for (const pattern of patterns) {
		if (existsSync(join(dir, pattern))) {
			return true;
		}
	}
	return false;
}

/**
 * Detect test framework from config files and dependencies.
 */
function detectTestFramework(repoPath: string): string | null {
	if (existsSync(join(repoPath, "vitest.config.ts")) || existsSync(join(repoPath, "vitest.config.js"))) {
		return "vitest";
	}
	if (existsSync(join(repoPath, "jest.config.ts")) || existsSync(join(repoPath, "jest.config.js"))) {
		return "jest";
	}
	if (existsSync(join(repoPath, ".mocharc.yml")) || existsSync(join(repoPath, ".mocharc.json"))) {
		return "mocha";
	}
	if (existsSync(join(repoPath, "pytest.ini")) || existsSync(join(repoPath, "pyproject.toml"))) {
		return "pytest";
	}

	// Check package.json
	try {
		const pkg = JSON.parse(readFileSync(join(repoPath, "package.json"), "utf-8"));
		const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };
		if (allDeps.vitest) {
			return "vitest";
		}
		if (allDeps.jest) {
			return "jest";
		}
		if (allDeps.mocha) {
			return "mocha";
		}
	} catch {
		// No package.json
	}

	return null;
}

/**
 * Detect the primary framework from config files.
 */
function detectFramework(repoPath: string): string | null {
	if (
		existsSync(join(repoPath, "next.config.ts")) ||
		existsSync(join(repoPath, "next.config.js")) ||
		existsSync(join(repoPath, "next.config.mjs"))
	) {
		return "next.js";
	}
	if (existsSync(join(repoPath, "nuxt.config.ts"))) {
		return "nuxt";
	}
	if (existsSync(join(repoPath, "angular.json"))) {
		return "angular";
	}
	if (existsSync(join(repoPath, "svelte.config.js"))) {
		return "svelte";
	}
	if (existsSync(join(repoPath, "vite.config.ts")) || existsSync(join(repoPath, "vite.config.js"))) {
		return "vite";
	}

	try {
		const pkg = JSON.parse(readFileSync(join(repoPath, "package.json"), "utf-8"));
		const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };
		if (allDeps.next) {
			return "next.js";
		}
		if (allDeps.react) {
			return "react";
		}
		if (allDeps.vue) {
			return "vue";
		}
		if (allDeps.express) {
			return "express";
		}
		if (allDeps.hono) {
			return "hono";
		}
	} catch {
		// No package.json
	}

	return null;
}

/**
 * Detect package directories in a monorepo.
 */
function detectPackageDirs(repoPath: string): string[] {
	const dirs: string[] = [];
	const candidates = ["packages", "apps", "libs", "modules", "services"];

	for (const candidate of candidates) {
		const candidatePath = join(repoPath, candidate);
		if (!existsSync(candidatePath)) {
			continue;
		}
		try {
			const entries = readdirSync(candidatePath, { withFileTypes: true });
			for (const entry of entries) {
				if (entry.isDirectory() && existsSync(join(candidatePath, entry.name, "package.json"))) {
					dirs.push(join(candidate, entry.name));
				}
			}
		} catch {
			// Skip
		}
	}

	// If no monorepo dirs found, treat root as the single package
	if (dirs.length === 0) {
		dirs.push(".");
	}

	return dirs;
}

/**
 * Compute test adjacency signals per package.
 */
function computeTestAdjacency(repoPath: string, packageDirs: string[], churnFiles?: string[]): TestAdjacencySignals {
	const isTestFile = (name: string) =>
		name.endsWith(".test.ts") ||
		name.endsWith(".test.tsx") ||
		name.endsWith(".test.js") ||
		name.endsWith(".spec.ts") ||
		name.endsWith(".spec.tsx") ||
		name.endsWith(".spec.js");

	const isSourceFile = (name: string) =>
		(name.endsWith(".ts") || name.endsWith(".tsx") || name.endsWith(".js") || name.endsWith(".jsx")) &&
		!isTestFile(name) &&
		!name.endsWith(".d.ts") &&
		!name.endsWith(".config.ts") &&
		!name.endsWith(".config.js");

	const packageTestAdjacency: TestAdjacencySignals["packageTestAdjacency"] = [];
	const churnSet = new Set(churnFiles || []);

	for (const pkgDir of packageDirs) {
		const fullPath = join(repoPath, pkgDir);
		const srcPath = existsSync(join(fullPath, "src")) ? join(fullPath, "src") : fullPath;

		const hasTestDir =
			existsSync(join(fullPath, "__tests__")) ||
			existsSync(join(fullPath, "test")) ||
			existsSync(join(fullPath, "tests"));

		const testFileCount = countFiles(fullPath, isTestFile);
		const sourceFileCount = countFiles(srcPath, isSourceFile);
		const testRatio = sourceFileCount > 0 ? testFileCount / sourceFileCount : 0;

		// Churn score: how many churning files are in this package
		let churnScore = 0;
		if (churnSet.size > 0) {
			for (const f of churnSet) {
				if (f.startsWith(pkgDir)) {
					churnScore++;
				}
			}
		}

		packageTestAdjacency.push({
			packagePath: pkgDir,
			hasTestDir: hasTestDir || testFileCount > 0,
			testFileCount,
			sourceFileCount,
			testRatio,
			churnScore,
		});
	}

	// Weakly tested hotspots: high churn packages with low test ratio
	const weaklyTestedHotspots = packageTestAdjacency
		.filter((p) => p.churnScore > 2 && p.testRatio < 0.3)
		.map((p) => p.packagePath);

	// Overall score: weighted average of test ratios
	const totalSource = packageTestAdjacency.reduce((s, p) => s + p.sourceFileCount, 0);
	const overallTestAdjacencyScore =
		totalSource > 0
			? Math.min(
					100,
					(packageTestAdjacency.reduce((s, p) => s + p.testRatio * p.sourceFileCount, 0) / totalSource) * 100,
				)
			: 0;

	return { packageTestAdjacency, weaklyTestedHotspots, overallTestAdjacencyScore };
}

/**
 * Detect sensitive surfaces (env files, credentials, CI secrets, infra state).
 */
function detectSensitiveSurfaces(repoPath: string): SensitiveSurfaceSignals {
	const envPatterns = [".env", ".env.local", ".env.development", ".env.production", ".env.staging"];
	const hasEnvFiles = envPatterns.some((p) => existsSync(join(repoPath, p)));

	const credPatterns = [".npmrc", ".pypirc", "docker-compose.yml", "docker-compose.yaml"];
	const hasCredentialConfigs = credPatterns.some((p) => existsSync(join(repoPath, p)));

	// Check for CI secrets in workflow files
	let hasCISecrets = false;
	const workflowDir = join(repoPath, ".github", "workflows");
	if (existsSync(workflowDir)) {
		try {
			const files = readdirSync(workflowDir);
			for (const f of files) {
				try {
					const content = readFileSync(join(workflowDir, f), "utf-8");
					if (content.includes("secrets.")) {
						hasCISecrets = true;
						break;
					}
				} catch {
					// Skip unreadable files
				}
			}
		} catch {
			// Skip
		}
	}

	const hasInfraState = existsSync(join(repoPath, "terraform.tfstate")) || existsSync(join(repoPath, ".terraform"));

	let sensitivePathCount = 0;
	if (hasEnvFiles) {
		sensitivePathCount += envPatterns.filter((p) => existsSync(join(repoPath, p))).length;
	}
	if (hasCredentialConfigs) {
		sensitivePathCount += credPatterns.filter((p) => existsSync(join(repoPath, p))).length;
	}
	if (hasCISecrets) {
		sensitivePathCount++;
	}
	if (hasInfraState) {
		sensitivePathCount++;
	}

	return { hasEnvFiles, hasCredentialConfigs, hasCISecrets, hasInfraState, sensitivePathCount };
}

export async function detectStructure(repoPath: string, emitter?: DiscoveryEmitter): Promise<RepoStructure> {
	const isTurbo = existsSync(join(repoPath, "turbo.json"));
	const isNx = existsSync(join(repoPath, "nx.json"));
	const isLerna = existsSync(join(repoPath, "lerna.json"));
	const isPnpmWorkspace = existsSync(join(repoPath, "pnpm-workspace.yaml"));

	let repoType: RepoStructure["repoType"] = "single";
	if (isTurbo) {
		repoType = "monorepo-turbo";
	} else if (isNx) {
		repoType = "monorepo-nx";
	} else if (isLerna) {
		repoType = "monorepo-lerna";
	} else if (isPnpmWorkspace) {
		repoType = "polyrepo";
	}

	// Detect package manager
	let packageManager: RepoStructure["packageManager"] = null;
	if (existsSync(join(repoPath, "pnpm-lock.yaml"))) {
		packageManager = "pnpm";
	} else if (existsSync(join(repoPath, "bun.lockb"))) {
		packageManager = "bun";
	} else if (existsSync(join(repoPath, "yarn.lock"))) {
		packageManager = "yarn";
	} else if (existsSync(join(repoPath, "package-lock.json"))) {
		packageManager = "npm";
	}

	// Config file count
	const configExtensions = [".json", ".yaml", ".yml", ".toml", ".config.ts", ".config.js", ".config.mjs"];
	let configFileCount = 0;
	try {
		const rootFiles = readdirSync(repoPath);
		for (const f of rootFiles) {
			if (configExtensions.some((ext) => f.endsWith(ext))) {
				configFileCount++;
			}
		}
	} catch {
		// Skip
	}

	// Gitignore complexity
	let gitignoreComplexity = 0;
	try {
		const gitignore = readFileSync(join(repoPath, ".gitignore"), "utf-8");
		gitignoreComplexity = gitignore.split("\n").filter((l) => l.trim() && !l.startsWith("#")).length;
	} catch {
		// No .gitignore
	}

	// Run independent git commands in parallel
	const [ageResult, countResult, branchResult] = await Promise.all([
		execFileAsync("git", ["log", "--reverse", "--format=%aI", "-1"], { cwd: repoPath, timeout: 5000 }).catch(
			() => ({ stdout: "" }),
		),
		execFileAsync("git", ["rev-list", "--count", "--all"], { cwd: repoPath, timeout: 5000 }).catch(() => ({
			stdout: "0",
		})),
		execFileAsync("git", ["branch", "-a", "--format=%(refname:short) %(committerdate:iso)"], {
			cwd: repoPath,
			timeout: 5000,
		}).catch(() => ({ stdout: "" })),
	]);

	let age = 0;
	if (ageResult.stdout.trim()) {
		const firstDate = new Date(ageResult.stdout.trim());
		age = Math.floor((Date.now() - firstDate.getTime()) / (24 * 60 * 60 * 1000));
	}

	const totalCommits = Number.parseInt(countResult.stdout.trim(), 10) || 0;

	let activeBranches = 0;
	const thirtyDaysAgo = Date.now() - 30 * 24 * 60 * 60 * 1000;
	for (const line of branchResult.stdout.split("\n").filter(Boolean)) {
		const parts = line.trim().split(/\s+/);
		if (parts.length >= 2) {
			const branchDate = new Date(parts.slice(1).join(" "));
			if (!Number.isNaN(branchDate.getTime()) && branchDate.getTime() > thirtyDaysAgo) {
				activeBranches++;
			}
		}
	}

	const packageDirs = detectPackageDirs(repoPath);
	const testAdjacency = computeTestAdjacency(repoPath, packageDirs);
	const sensitiveSurfaces = detectSensitiveSurfaces(repoPath);

	const structure: RepoStructure = {
		repoType,
		framework: detectFramework(repoPath),
		packageManager,
		hasCI:
			existsSync(join(repoPath, ".github", "workflows")) ||
			existsSync(join(repoPath, ".gitlab-ci.yml")) ||
			existsSync(join(repoPath, ".circleci")),
		hasDocker: existsSync(join(repoPath, "Dockerfile")) || existsSync(join(repoPath, "docker-compose.yml")),
		testFramework: detectTestFramework(repoPath),
		configFileCount,
		gitignoreComplexity,
		age,
		totalCommits,
		activeBranches,
		testAdjacency,
		sensitiveSurfaces,
	};

	// Emit discoveries
	if (emitter && sensitiveSurfaces.hasEnvFiles) {
		emitter.emit("discovery", {
			source: "structure",
			confidence: 0.95,
			message: "Detected environment variables",
			detailMessage: "Vreko ignores .env files completely",
		});
	}

	if (emitter && testAdjacency.weaklyTestedHotspots.length > 0) {
		emitter.emit("discovery", {
			source: "structure",
			confidence: 0.87,
			message: `${testAdjacency.weaklyTestedHotspots.length} package(s) with high churn but low test coverage`,
			detailMessage: "Vreko will monitor these as fragile zones",
		});
	}

	return structure;
}
