import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { DiscoveryEmitter, ReflogSignals, TimeWindow } from "./types";

const execFileAsync = promisify(execFile);

/**
 * Parse an ISO date string from a reflog line.
 * Reflog format: `sha1 ref@{ISO-DATE}: action: description`
 */
function parseDateFromLine(line: string): Date | null {
	const match = line.match(/\{([^}]+)\}/);
	if (!match) {
		return null;
	}
	const d = new Date(match[1]);
	return Number.isNaN(d.getTime()) ? null : d;
}

/**
 * Extract the branch name from a reflog line.
 * E.g., `abc123 refs/heads/main@{2026-01-01}: ...` → `main`
 */
function parseBranchFromLine(line: string): string | null {
	const match = line.match(/refs\/heads\/([^@]+)@/);
	return match ? match[1] : null;
}

export async function scanReflog(repoPath: string, emitter?: DiscoveryEmitter): Promise<ReflogSignals> {
	const signals: ReflogSignals = {
		forceResetRate: 0,
		rebaseFrequency: 0,
		branchAbandonmentRate: 0,
		contextSwitchRate: 0,
		peakActivityWindows: [],
		weekendActivityRatio: 0,
		lateNightRatio: 0,
		resetToHEADCount: 0,
		reflogChurnByBranch: new Map(),
		avgTimeBetweenResets: 0,
	};

	try {
		const { stdout } = await execFileAsync("git", ["reflog", "--all", "--date=iso"], {
			cwd: repoPath,
			maxBuffer: 10 * 1024 * 1024,
			timeout: 10000,
		});

		const lines = stdout.split("\n").filter(Boolean);
		if (lines.length === 0) {
			return signals;
		}

		// Collect timestamps and classify entries
		const timestamps: Date[] = [];
		const resetTimestamps: number[] = [];
		let resetCount = 0;
		let forceResetCount = 0;
		let rebaseCount = 0;
		let checkoutCount = 0;
		let weekendCount = 0;
		let lateNightCount = 0;
		const hourCounts = new Array<number>(24).fill(0);
		const branchesCreated = new Set<string>();
		const branchesMerged = new Set<string>();
		const branchChurn = new Map<string, number>();

		for (const line of lines) {
			const date = parseDateFromLine(line);
			if (date) {
				timestamps.push(date);
				const hour = date.getHours();
				hourCounts[hour]++;
				const day = date.getDay();
				if (day === 0 || day === 6) {
					weekendCount++;
				}
				if (hour >= 22 || hour < 5) {
					lateNightCount++;
				}
			}

			const branch = parseBranchFromLine(line);
			if (branch) {
				branchChurn.set(branch, (branchChurn.get(branch) || 0) + 1);
			}

			// Count reset-to-HEAD events (the "oh no" moments)
			if (line.includes("reset: moving to HEAD")) {
				resetCount++;
				if (date) {
					resetTimestamps.push(date.getTime());
				}
			}

			// Force resets and hard resets
			if (line.includes("reset: moving to") && !line.includes("reset: moving to HEAD")) {
				forceResetCount++;
				if (date) {
					resetTimestamps.push(date.getTime());
				}
			}

			// Rebase events
			if (line.includes("rebase")) {
				rebaseCount++;
			}

			// Checkout / context switch events
			if (line.includes("checkout: moving from")) {
				checkoutCount++;
			}

			// Branch creation tracking
			if (line.includes("branch: Created from")) {
				if (branch) {
					branchesCreated.add(branch);
				}
			}

			// Merge tracking (branch was merged)
			if (line.includes("merge")) {
				const mergedMatch = line.match(/merge\s+(\S+)/);
				if (mergedMatch) {
					branchesMerged.add(mergedMatch[1].replace(/[:;]$/, ""));
				}
			}
		}

		// Compute time span in weeks for rate calculations
		const sortedTimestamps = timestamps.map((d) => d.getTime()).sort((a, b) => a - b);
		const timeSpanMs =
			sortedTimestamps.length > 1
				? sortedTimestamps[sortedTimestamps.length - 1] - sortedTimestamps[0]
				: 7 * 24 * 60 * 60 * 1000; // default 1 week
		const weeks = Math.max(timeSpanMs / (7 * 24 * 60 * 60 * 1000), 1);
		const days = Math.max(timeSpanMs / (24 * 60 * 60 * 1000), 1);

		signals.resetToHEADCount = resetCount;
		signals.forceResetRate = (forceResetCount + resetCount) / weeks;
		signals.rebaseFrequency = rebaseCount / weeks;
		signals.contextSwitchRate = checkoutCount / days;

		// Branch abandonment: created but never merged
		const abandoned = [...branchesCreated].filter((b) => !branchesMerged.has(b));
		signals.branchAbandonmentRate = branchesCreated.size > 0 ? (abandoned.length / branchesCreated.size) * 100 : 0;

		// Temporal patterns
		signals.weekendActivityRatio = lines.length > 0 ? weekendCount / lines.length : 0;
		signals.lateNightRatio = lines.length > 0 ? lateNightCount / lines.length : 0;

		// Peak activity windows: find hours with activity > mean + 1 stddev
		const meanActivity = lines.length / 24;
		const stddev = Math.sqrt(hourCounts.reduce((sum, c) => sum + (c - meanActivity) ** 2, 0) / 24);
		const threshold = meanActivity + stddev;
		const peakWindows: TimeWindow[] = [];
		let windowStart: number | null = null;
		for (let h = 0; h < 24; h++) {
			if (hourCounts[h] > threshold) {
				if (windowStart === null) {
					windowStart = h;
				}
			} else {
				if (windowStart !== null) {
					peakWindows.push({ startHour: windowStart, endHour: h });
					windowStart = null;
				}
			}
		}
		if (windowStart !== null) {
			peakWindows.push({ startHour: windowStart, endHour: 24 });
		}
		signals.peakActivityWindows = peakWindows;

		// Reflog churn by branch
		signals.reflogChurnByBranch = branchChurn;

		// Average time between resets
		if (resetTimestamps.length > 1) {
			const sorted = resetTimestamps.sort((a, b) => a - b);
			let totalGap = 0;
			for (let i = 1; i < sorted.length; i++) {
				totalGap += sorted[i] - sorted[i - 1];
			}
			// Convert to minutes
			signals.avgTimeBetweenResets = totalGap / (sorted.length - 1) / (1000 * 60);
		}

		// Emit discoveries
		if (emitter && resetCount > 5) {
			emitter.emit("discovery", {
				source: "reflog",
				confidence: 0.9,
				message: `Found ${resetCount} reset events in your history`,
				detailMessage: "Vreko will learn your rollback patterns",
			});
		}

		if (emitter && signals.lateNightRatio > 0.2) {
			emitter.emit("discovery", {
				source: "reflog",
				confidence: 0.88,
				message: `${Math.round(signals.lateNightRatio * 100)}% of git activity happens after 10pm`,
				detailMessage: "Vreko will increase protection during late-night sessions",
			});
		}
	} catch (_error) {
		// If timeout or error, degrade gracefully  -  return zero signals
	}

	return signals;
}
