import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type {
	CoChangeEdge,
	CommitDiffusionSignals,
	DiscoveryEmitter,
	FileChurnEntry,
	GitLogSignals,
	RollbackCorrelationSignals,
} from "./types";

const execFileAsync = promisify(execFile);

/**
 * Lockfile basenames, dependency manifests, and generated-file patterns that must
 * never appear in fragility rankings.  High-churn by tooling definition  -  not by
 * developer instability.
 */
const ARTIFACT_BASENAMES = new Set([
	"pnpm-lock.yaml",
	"yarn.lock",
	"package-lock.json",
	"bun.lockb",
	"Gemfile.lock",
	"Cargo.lock",
	"poetry.lock",
	"go.sum",
	"composer.lock",
	"package.json",
	"apple-touch-icon.png",
	"favicon.ico",
	"favicon-16x16.png",
	"favicon-32x32.png",
	"icon-192.png",
	"icon-512.png",
]);

// Only directory NAMES that are unambiguously build outputs or caches.
// NOTE: "build" and "out" are intentionally excluded  -  they are too commonly
// used as source directory names (e.g. packages/next/src/build/).
const ARTIFACT_BUILD_SEGMENTS = new Set(["dist", ".next", "__generated__", ".turbo", ".cache"]);

/**
 * Returns true when a file path is a tooling artifact (lockfile, generated output,
 * dependency manifest) that should be excluded from fragility and co-change rankings.
 */
export function isArtifactFile(filePath: string): boolean {
	const parts = filePath.split("/");
	const basename = parts[parts.length - 1];

	// Exact-basename matches
	if (ARTIFACT_BASENAMES.has(basename)) {
		return true;
	}

	// Generated-file suffix patterns
	if (
		basename.endsWith(".d.ts") ||
		basename.endsWith(".gen.ts") ||
		basename.endsWith(".generated.ts") ||
		basename.endsWith(".gen.js") ||
		basename.endsWith(".generated.js") ||
		basename.endsWith(".min.js") ||
		basename.endsWith(".min.css")
	) {
		return true;
	}

	// Image assets — never developer coupling signals
	if (
		basename.endsWith(".png") ||
		basename.endsWith(".ico") ||
		basename.endsWith(".jpg") ||
		basename.endsWith(".jpeg") ||
		basename.endsWith(".svg") ||
		basename.endsWith(".gif") ||
		basename.endsWith(".webp")
	) {
		return true;
	}

	// Build-output directory segments (any segment in the path)
	for (const segment of parts.slice(0, -1)) {
		if (ARTIFACT_BUILD_SEGMENTS.has(segment)) {
			return true;
		}
	}

	return false;
}

interface ParsedCommit {
	sha: string;
	date: Date;
	parentCount: number;
	files: Array<{ path: string; added: number; deleted: number }>;
	isRevert: boolean;
	subject: string;
}

function topLevelDir(filePath: string): string {
	const parts = filePath.split("/");
	return parts.length > 1 ? parts[0] : ".";
}

/**
 * Check if two timestamps are within N hours of each other.
 */
function withinHours(a: Date, b: Date, hours: number): boolean {
	return Math.abs(a.getTime() - b.getTime()) <= hours * 60 * 60 * 1000;
}

export async function analyzeGitLog(repoPath: string, emitter?: DiscoveryEmitter): Promise<GitLogSignals> {
	const signals: GitLogSignals = {
		avgCommitsPerDay: 0,
		commitFrequencyVariance: 0,
		largeCommitRatio: 0,
		diffusion: {
			avgFilesTouchedPerCommit: 0,
			crossDirectoryDiffusionRate: 0,
			rollbackAdjacentCommitRate: 0,
			largeSessionClusterRate: 0,
			maxSingleCommitSpread: 0,
		},
		rollbackCorrelation: {
			resetAfterLargeCommitRate: 0,
			resetAfterBranchSwitchRate: 0,
			resetAfterLateNightRate: 0,
			resetAfterCrossPackageRate: 0,
			branchSpecificRollbackDensity: new Map(),
			medianTimeToRecovery: 0,
			topRecoveryTrigger: "large-commit",
		},
		fileChurnRanking: [],
		coChangeGraph: [],
		hotspotFiles: [],
		contributorCount: 0,
		busFactorEstimate: 0,
		mergeConflictFrequency: 0,
	};

	try {
		const { stdout: logStdout } = await execFileAsync(
			"git",
			// --no-merges: merge commits produce empty numstat output  -  file changes
			// were already counted in the original feature commits, so merge commits
			// only add noise and cause fileChurnRanking to appear empty on repos with
			// dense merge-commit histories (e.g. large open-source monorepos on canary branches).
			//
			// Omit --all: scanning every ref (tags, remote branches) on large repos like
			// Next.js (~34k commits) exhausts the 10-second timeout and SIGTERM-kills the
			// child process, causing the catch block to swallow the error and return all-zero
			// signals. HEAD-reachable history is sufficient for behavioral intelligence  -  the
			// developer's active branch is what matters, not all historical branches.
			["log", "--format=COMMIT:%H %aI %P|%s", "--numstat", "--no-merges", "-n", "10000"],
			{
				cwd: repoPath,
				maxBuffer: 20 * 1024 * 1024,
				// 60 s: gives large monorepos (Next.js-scale, ~34k commits HEAD-reachable)
				// enough headroom while still bounding the scan. The scan result is cached
				// for 24 hours so a one-time 30-60s wait is acceptable on first run.
				timeout: 60000,
			},
		);

		const commits = parseLogOutput(logStdout);
		if (commits.length === 0) {
			return signals;
		}

		// Time span
		const dates = commits.map((c) => c.date.getTime()).sort((a, b) => a - b);
		const timeSpanMs = dates[dates.length - 1] - dates[0];
		const days = Math.max(timeSpanMs / (24 * 60 * 60 * 1000), 1);

		// Basic commit patterns
		signals.avgCommitsPerDay = commits.length / days;

		// Commit frequency variance: std dev of commits per day
		const commitsByDay = new Map<string, number>();
		for (const c of commits) {
			const dayKey = c.date.toISOString().slice(0, 10);
			commitsByDay.set(dayKey, (commitsByDay.get(dayKey) || 0) + 1);
		}
		const dailyCounts = [...commitsByDay.values()];
		const mean = dailyCounts.reduce((a, b) => a + b, 0) / Math.max(dailyCounts.length, 1);
		signals.commitFrequencyVariance = Math.sqrt(
			dailyCounts.reduce((sum, c) => sum + (c - mean) ** 2, 0) / Math.max(dailyCounts.length, 1),
		);

		// Large commit ratio (touching 10+ files)
		const largeCommits = commits.filter((c) => c.files.length >= 10);
		signals.largeCommitRatio = (largeCommits.length / commits.length) * 100;

		signals.diffusion = computeDiffusion(commits);

		// Rollback correlation
		signals.rollbackCorrelation = computeRollbackCorrelation(commits);

		// File churn ranking
		signals.fileChurnRanking = computeFileChurn(commits);

		// Co-change graph
		signals.coChangeGraph = computeCoChangeGraph(commits);

		// Hotspot files: reverted files ranked by revert rate first, then high-churn
		// files as fallback. The old sort (changeCount × (revertCount+1)) rewarded
		// raw frequency  -  lockfiles ranked first even after exclusion at the churn map
		// level if they somehow survived. Revert-rate sort surfaces genuinely fragile
		// files ahead of merely busy ones.
		signals.hotspotFiles = signals.fileChurnRanking
			.filter((f) => f.revertCount > 0 || f.changeCount > 5)
			.sort((a, b) => {
				// Reverted files always rank above never-reverted files
				const hasRevertA = a.revertCount > 0 ? 1 : 0;
				const hasRevertB = b.revertCount > 0 ? 1 : 0;
				if (hasRevertB !== hasRevertA) return hasRevertB - hasRevertA;
				// Both reverted: sort by revert rate (higher = more fragile)
				if (a.revertCount > 0 && b.revertCount > 0) {
					return b.revertCount / b.changeCount - a.revertCount / a.changeCount;
				}
				// Both zero-revert: fall back to changeCount
				return b.changeCount - a.changeCount;
			})
			.slice(0, 10)
			.map((f) => f.path);

		// Contributor count
		const { stdout: shortlogOut } = await execFileAsync("git", ["shortlog", "-sn", "--all"], {
			cwd: repoPath,
			maxBuffer: 1024 * 1024,
			timeout: 10000,
		});
		const contributors = shortlogOut.split("\n").filter(Boolean);
		signals.contributorCount = contributors.length;

		// Bus factor: count files only one contributor touches
		// Simplified: if single contributor, bus factor = 1
		signals.busFactorEstimate = Math.max(
			1,
			Math.min(signals.contributorCount, Math.ceil(signals.contributorCount * 0.3)),
		);

		// Merge conflict frequency
		const mergeCommits = commits.filter((c) => c.parentCount > 1);
		signals.mergeConflictFrequency = commits.length > 0 ? (mergeCommits.length / commits.length) * 100 : 0;

		// Emit discoveries
		if (emitter && signals.coChangeGraph.length > 0) {
			const topPair = signals.coChangeGraph[0];
			if (topPair.confidence > 0.9) {
				emitter.emit("discovery", {
					source: "gitlog",
					confidence: topPair.confidence,
					message: `${topPair.fileA} and ${topPair.fileB} change together ${Math.round(topPair.confidence * 100)}% of the time`,
					detailMessage: "Vreko will track this relationship",
					relatedInsightId: "co-change-instability",
				});
			}
		}

		if (emitter && signals.avgCommitsPerDay > 10) {
			emitter.emit("discovery", {
				source: "gitlog",
				confidence: 0.88,
				message: "High commit frequency detected",
				detailMessage: "Vreko can group these logically",
			});
		}
	} catch (_error) {
		// Degrade gracefully
	}

	return signals;
}

/**
 * Parse the COMMIT: delimited log output.
 */
function parseLogOutput(stdout: string): ParsedCommit[] {
	const commits: ParsedCommit[] = [];
	const lines = stdout.split("\n");
	let current: ParsedCommit | null = null;

	for (const line of lines) {
		if (line.startsWith("COMMIT:")) {
			if (current) {
				commits.push(current);
			}
			const rest = line.slice(7); // Remove "COMMIT:"
			const pipeIdx = rest.indexOf("|");
			if (pipeIdx === -1) {
				continue;
			}

			const metaPart = rest.slice(0, pipeIdx).trim();
			const subject = rest.slice(pipeIdx + 1);
			const parts = metaPart.split(/\s+/);
			if (parts.length < 2) {
				continue;
			}

			const sha = parts[0];
			const dateStr = parts[1];
			const parentHashes = parts.slice(2);
			const date = new Date(dateStr);
			if (Number.isNaN(date.getTime())) {
				continue;
			}

			current = {
				sha,
				date,
				parentCount: parentHashes.length,
				files: [],
				isRevert: subject.toLowerCase().startsWith("revert"),
				subject,
			};
		} else if (current && line.trim()) {
			const parts = line.split("\t");
			if (parts.length >= 3) {
				const added = parts[0] === "-" ? 0 : Number.parseInt(parts[0], 10) || 0;
				const deleted = parts[1] === "-" ? 0 : Number.parseInt(parts[1], 10) || 0;
				current.files.push({ path: parts[2], added, deleted });
			}
		}
	}
	if (current) {
		commits.push(current);
	}

	return commits;
}

function computeDiffusion(commits: ParsedCommit[]): CommitDiffusionSignals {
	if (commits.length === 0) {
		return {
			avgFilesTouchedPerCommit: 0,
			crossDirectoryDiffusionRate: 0,
			rollbackAdjacentCommitRate: 0,
			largeSessionClusterRate: 0,
			maxSingleCommitSpread: 0,
		};
	}

	const fileCounts = commits.map((c) => c.files.length);
	const avgFilesTouchedPerCommit = fileCounts.reduce((a, b) => a + b, 0) / commits.length;

	// Cross-directory diffusion: commits spanning 2+ top-level dirs
	const crossDirCommits = commits.filter((c) => {
		const dirs = new Set(c.files.map((f) => topLevelDir(f.path)));
		return dirs.size >= 2;
	});
	const crossDirectoryDiffusionRate = (crossDirCommits.length / commits.length) * 100;

	// Rollback-adjacent: commits followed by a revert within 6h
	let rollbackAdjacentCount = 0;
	const sortedByDate = [...commits].sort((a, b) => a.date.getTime() - b.date.getTime());
	for (let i = 0; i < sortedByDate.length; i++) {
		for (let j = i + 1; j < sortedByDate.length; j++) {
			if (!withinHours(sortedByDate[i].date, sortedByDate[j].date, 6)) {
				break;
			}
			if (sortedByDate[j].isRevert) {
				rollbackAdjacentCount++;
				break;
			}
		}
	}
	const rollbackAdjacentCommitRate = (rollbackAdjacentCount / commits.length) * 100;

	// Large session clusters: 5+ commits within 2h windows
	let clusterCount = 0;
	for (let i = 0; i < sortedByDate.length; i++) {
		let windowEnd = i;
		while (
			windowEnd + 1 < sortedByDate.length &&
			withinHours(sortedByDate[i].date, sortedByDate[windowEnd + 1].date, 2)
		) {
			windowEnd++;
		}
		if (windowEnd - i + 1 >= 5) {
			clusterCount++;
			i = windowEnd; // skip to end of cluster
		}
	}
	const largeSessionClusterRate = (clusterCount / Math.max(commits.length / 5, 1)) * 100;

	const maxSingleCommitSpread = Math.max(...fileCounts, 0);

	return {
		avgFilesTouchedPerCommit,
		crossDirectoryDiffusionRate,
		rollbackAdjacentCommitRate,
		largeSessionClusterRate,
		maxSingleCommitSpread,
	};
}

function computeRollbackCorrelation(commits: ParsedCommit[]): RollbackCorrelationSignals {
	const result: RollbackCorrelationSignals = {
		resetAfterLargeCommitRate: 0,
		resetAfterBranchSwitchRate: 0,
		resetAfterLateNightRate: 0,
		resetAfterCrossPackageRate: 0,
		branchSpecificRollbackDensity: new Map(),
		medianTimeToRecovery: 0,
		topRecoveryTrigger: "large-commit",
	};

	const sorted = [...commits].sort((a, b) => a.date.getTime() - b.date.getTime());
	const reverts = sorted.filter((c) => c.isRevert);
	if (reverts.length === 0) {
		return result;
	}

	let afterLargeCount = 0;
	let afterLateNightCount = 0;
	let afterCrossPackageCount = 0;
	const recoveryTimes: number[] = [];

	for (const revert of reverts) {
		// Find the preceding non-revert commit
		const precedingIdx = sorted.findIndex((c) => c.sha === revert.sha) - 1;
		if (precedingIdx < 0) {
			continue;
		}

		// biome-ignore lint/correctness/noUnreachable: false positive  -  precedingIdx >= 0 guaranteed by continue above
		for (let i = precedingIdx; i >= 0; i--) {
			const preceding = sorted[i];
			if (!withinHours(preceding.date, revert.date, 6)) {
				break;
			}

			const timeDiff = (revert.date.getTime() - preceding.date.getTime()) / (1000 * 60);
			recoveryTimes.push(timeDiff);

			// After large commit
			if (preceding.files.length >= 5) {
				afterLargeCount++;
			}

			// After late night
			if (preceding.date.getHours() >= 22 || preceding.date.getHours() < 5) {
				afterLateNightCount++;
			}

			// After cross-package
			const dirs = new Set(preceding.files.map((f) => topLevelDir(f.path)));
			if (dirs.size >= 2) {
				afterCrossPackageCount++;
			}

			break; // only look at immediate predecessor
		}
	}

	const total = Math.max(reverts.length, 1);
	result.resetAfterLargeCommitRate = (afterLargeCount / total) * 100;
	result.resetAfterLateNightRate = (afterLateNightCount / total) * 100;
	result.resetAfterCrossPackageRate = (afterCrossPackageCount / total) * 100;

	// Median time to recovery
	if (recoveryTimes.length > 0) {
		recoveryTimes.sort((a, b) => a - b);
		const mid = Math.floor(recoveryTimes.length / 2);
		result.medianTimeToRecovery =
			recoveryTimes.length % 2 === 0 ? (recoveryTimes[mid - 1] + recoveryTimes[mid]) / 2 : recoveryTimes[mid];
	}

	// Top recovery trigger
	const triggers = {
		"large-commit": afterLargeCount,
		"late-night": afterLateNightCount,
		"cross-package": afterCrossPackageCount,
		"branch-switch": 0,
	};
	result.topRecoveryTrigger = Object.entries(triggers).sort((a, b) => b[1] - a[1])[0][0];

	return result;
}

function computeFileChurn(commits: ParsedCommit[]): FileChurnEntry[] {
	const churnMap = new Map<
		string,
		{ changeCount: number; totalLines: number; revertCount: number; lastChanged: Date }
	>();

	for (const commit of commits) {
		for (const file of commit.files) {
			// Skip lockfiles, package.json, and generated outputs  -  they are high-churn
			// by tooling definition, not developer instability, and must not pollute
			// fragility rankings (pnpm-lock.yaml would otherwise always top the list).
			if (isArtifactFile(file.path)) continue;

			const entry = churnMap.get(file.path) || {
				changeCount: 0,
				totalLines: 0,
				revertCount: 0,
				lastChanged: commit.date,
			};
			entry.changeCount++;
			entry.totalLines += file.added + file.deleted;
			if (commit.isRevert) {
				entry.revertCount++;
			}
			if (commit.date > entry.lastChanged) {
				entry.lastChanged = commit.date;
			}
			churnMap.set(file.path, entry);
		}
	}

	return [...churnMap.entries()]
		.map(([path, data]) => ({
			path,
			changeCount: data.changeCount,
			avgLinesChanged: data.changeCount > 0 ? data.totalLines / data.changeCount : 0,
			revertCount: data.revertCount,
			lastChanged: data.lastChanged.toISOString(),
		}))
		.sort((a, b) => b.changeCount - a.changeCount)
		.slice(0, 50); // top 50 files
}

function computeCoChangeGraph(commits: ParsedCommit[]): CoChangeEdge[] {
	// Count how often each pair of files appears in the same commit
	const pairCounts = new Map<string, number>();
	const fileCounts = new Map<string, number>();

	for (const commit of commits) {
		const paths = commit.files.map((f) => f.path);
		for (const p of paths) {
			fileCounts.set(p, (fileCounts.get(p) || 0) + 1);
		}
		// Only consider commits with 2-20 files (too many files = noise)
		if (paths.length < 2 || paths.length > 20) {
			continue;
		}
		for (let i = 0; i < paths.length; i++) {
			for (let j = i + 1; j < paths.length; j++) {
				const key = [paths[i], paths[j]].sort().join("|||");
				pairCounts.set(key, (pairCounts.get(key) || 0) + 1);
			}
		}
	}

	const edges: CoChangeEdge[] = [];
	for (const [key, count] of pairCounts) {
		if (count < 3) {
			continue; // filter noise
		}
		const [fileA, fileB] = key.split("|||");

		// Exclude pairs where BOTH files are tooling artifacts  -  e.g. pnpm-lock.yaml
		// always co-changes with package.json on every `pnpm install`. That is not a
		// developer coupling insight; it is package manager bookkeeping. Mixed pairs
		// (one artifact + one source) are kept because they can represent real signals.
		if (isArtifactFile(fileA) && isArtifactFile(fileB)) {
			continue;
		}

		const maxChanges = Math.max(fileCounts.get(fileA) || 1, fileCounts.get(fileB) || 1);
		edges.push({
			fileA,
			fileB,
			coChangeCount: count,
			confidence: count / maxChanges,
		});
	}

	return edges.sort((a, b) => b.confidence - a.confidence).slice(0, 20);
}
